     * @deprecated Recommend {@link MethodUtils#findMethod(Class, String, Class[])}
     */
    @Deprecated
    public static Method findMethodByMethodName(Class<?> clazz, String methodName)
            throws NoSuchMethodException, ClassNotFoundException {
